arguments.command:
# For the two unknown addresses (0x2f4b20, 0x2f4c84 in SGen worker thread),
# find the containing function via nm
aarch64-linux-gnu-nm -n /tmp/libmonosgen-debug 2>/dev/null | awk '
  { addr = strtonum("0x" $1) }
  addr <= 0x2f4b20 { f1_addr=$1; f1_name=$3 }
  addr <= 0x2f4c84 { f2_addr=$1; f2_name=$3 }
  END { print "0x2f4b20 is in: " f1_name " (at 0x" f1_addr ")"; print "0x2f4c84 is in: " f2_name " (at 0x" f2_addr ")" }
'

